arguments.old:
module bore_cut() {
    translate([4, hinge_y, hinge_z]) rotate([0, 90, 0])
        cylinder(h = 72, r = bore_r, $fn = 32);
}

arguments.new:
bore_fr = pin_r * cos(22.5) + 0.45;   // bore facet distance: uniform 0.45 gap around the pin
bore_oct_r = bore_fr / cos(22.5);
module bore_cut() {
    // octagonal bore, same orientation as the pin: flat-to-flat gap 0.45 everywhere
    extrude_yz(oct_pts(bore_oct_r), 4, 72, hinge_y, hinge_z);
}
